import { IRequestParams, IResultContent, request } from "@fanfanlo";
import { IRequestOptions } from "../IRequestOptions";
import { tms } from "../tms";
import type { IProjectInput, IProjectProject } from "./types";

/**
 * 创建项目的请求参数
 */
export interface ICreateProjectParams extends IRequestParams {
    data: IProjectInput;
}

/**
 * 创建项目的返回结果
 */
export interface ICreateProjectResult extends IResultContent {
    project?: IProjectProject;
}

/**
 * 创建项目
 * @param opts 请求选项
 * @returns 创建结果
 */
export async function createProject(opts: IRequestOptions<ICreateProjectParams>) {
    console.log('[createProject] 开始创建项目, params:', JSON.stringify(opts.params));

    const res = await request<ICreateProjectResult>(
        tms.TProject,
        tms.MProjectCreateProject,
        opts.params,
        opts.gateway,
        opts.handler
    );

    if (res.shellIsOk) {
        console.log('[createProject] 请求成功, shellIsOk:', res.shellIsOk);
    } else {
        console.log('[createProject] 请求失败, shellIsOk:', res.shellIsOk, 'err:', res.err);
    }

    if (res.dataIsOk) {
        console.log('[createProject] 数据正常, dataIsOk:', res.dataIsOk);
    } else {
        console.log('[createProject] 数据异常, dataIsOk:', res.dataIsOk, 'errMsg:', res.data?.errMsg, 'errCode:', res.data?.errCode);
    }

    if (res.data) {
        if (res.data.is_ok) {
            console.log('[createProject] 创建成功, project.uuid:', res.data.project?.uuid);
        } else {
            console.log('[createProject] 创建失败, msg:', res.data.msg);
        }
    } else {
        console.log('[createProject] 无返回数据');
    }

    return res;
}

export default createProject;
