import { ITriggerData, ITriggerJavaData, ITriggerShellData, TriggerListContext, TriggerGroupContext } from "@droid/project-v2-interface"
import { Box } from "@mui/material"
import { Log, getUpdateVersion, useWatchUpdates } from "@fanfanlo"
import { Trigger } from "./trigger/Trigger"
import { useContext } from "react"

const fileLog = new Log(true, 'TriggerList');
fileLog.pause = true;

export function TriggerList(){
    const triggerGroup = useContext(TriggerGroupContext)
    // 修改：监听children而不是list（web端主要使用children）
    const [children] = useWatchUpdates(triggerGroup.children)

    fileLog.log('triggerGroup=', JSON.stringify(triggerGroup));

    // 使用 children 获取完整对象，而不是 list
    const childrenArray = triggerGroup.children || [];
    fileLog.log('children.length=', childrenArray.length);

    return (
        <TriggerListContext.Provider value={childrenArray}>
            <Box>
                {childrenArray.map((trigger, index) => {
                    fileLog.log(`render trigger index=${index}, trigger=`, trigger);
                    if (!trigger) {
                        fileLog.error(`trigger is undefined at index=${index}`);
                        return null;
                    }
                    return <Trigger key={getUpdateVersion(trigger).version} triggerData={trigger} triggerGroup={triggerGroup} index={index} />
                })}
            </Box>
        </TriggerListContext.Provider>
    )
}

