import { ITriggerJavaData, ITriggerShellData, TriggerContext, ITriggerData, getTriggerUtils, ITriggerGroup } from "@droid/project-v2-interface";
import { Box, Button } from "@mui/material";
import { toProxy, ButtonConfirm, Log } from "@fanfanlo";

const fileLog = new Log(false, 'Trigger_f');
fileLog.pause = true;
fileLog.childrenPaused = true;

interface TriggerProps {
    triggerData: ITriggerData<ITriggerShellData, ITriggerJavaData>;
    triggerGroup: ITriggerGroup;
    index: number;
}

export function Trigger({ triggerData, triggerGroup, index }: TriggerProps) {
    const uiLog = fileLog.sub(false, 'trigger_ui')
    uiLog.pause = true
    uiLog.childrenPaused = true
    uiLog.log('triggerData.type', triggerData.type)
    uiLog.log('index', index)
    const utils = getTriggerUtils(triggerData.type)
    const onDeleteComfirmed = () => {
        uiLog.log('[onDeleteComfirmed] 开始删除 trigger')
        uiLog.log('[onDeleteComfirmed] triggerGroup.children.length =', triggerGroup.children?.length)
        uiLog.log('[onDeleteComfirmed] index =', index)
        uiLog.log('[onDeleteComfirmed] triggerData.ulid =', triggerData.ulid)
        // 直接使用 index 删除，不需要再查找
        if (!triggerGroup.children) {
            uiLog.error('[onDeleteComfirmed] triggerGroup.children 不存在')
            return
        }
        if (index < 0 || index >= triggerGroup.children.length) {
            uiLog.error('[onDeleteComfirmed] index 越界')
            return
        }
        toProxy(triggerGroup.children).splice(index, 1)
        uiLog.log('[onDeleteComfirmed] 删除成功，新 triggerGroup.children.length =', triggerGroup.children.length)
    }
    // uiLog.info('utils', utils)
    return (
        <TriggerContext.Provider value={triggerData}>
            <Box>
                {utils.UI(triggerData)}
                <Box sx={{textAlign:"center"}}>
                    <ButtonConfirm title="删除触发" content="确定删除本触发吗？" onConfirm={onDeleteComfirmed}>
                        <Button
                        data-testid={`Trigger__deleteButton__01JFXYZA7P1Q2R3S4T5U6V7W8__${index}`}
                        id="del-trigger-btn"
                        data-id="del-trigger-btn"
                        >删除</Button>
                    </ButtonConfirm>
                </Box>
            </Box>
        </TriggerContext.Provider>
    )
}

    
