import {
  childToProjectDataUtils,
  createDefaultTriggerAction,
  TriggerActionGroupContext,
  ITriggerActionGroup,
} from '@droid/project-v2-interface';
import { EditableText, getUpdateVersion, Log, toParent, useWatchListOperation, useProxyWatch } from '@fanfanlo';
import AddIcon from '@mui/icons-material/Add';
import HandymanIcon from '@mui/icons-material/Handyman';
import NotificationsNoneIcon from '@mui/icons-material/NotificationsNone';
import TableRowsIcon from '@mui/icons-material/TableRows';
import { Box, Grid2, IconButton, Switch, FormControlLabel, Tooltip } from '@mui/material';
import { useContext, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { ProjectCategoryUIConfigContext, ProjectEditInfoContext } from '../contexts';
import { TriggerAction } from './trigger-action/TriggerAction';

const fileLog = new Log(true, 'TriggerActionGroup');
fileLog.pause = true;
fileLog.childrenPaused = true;
export function TriggerActionGroup({
  triggerActionGroup: propsTriggerActionGroup
}: {
  triggerActionGroup?: ITriggerActionGroup
}) {
  const { t } = useTranslation('droid-project/project/ui/project/edit-project/trigger-action-group/content');
  const editInfo = useContext(ProjectEditInfoContext);
  const uiConfig = useContext(ProjectCategoryUIConfigContext);
  const contextTriggerActionGroup = useContext(TriggerActionGroupContext);

  // 优先使用 props，其次使用 Context（不再兼容旧的 project.triggerActionGroup）
  const triggerActionGroup = propsTriggerActionGroup || contextTriggerActionGroup;

  if (!triggerActionGroup) {
    fileLog.error('[TriggerActionGroup] triggerActionGroup 不存在');
    return null;
  }

  fileLog.log(`[TriggerActionGroup] triggerActionGroup.ulid=${triggerActionGroup.ulid}`);
  fileLog.log(`[TriggerActionGroup] uiConfig.allowAddGroup=${uiConfig.allowAddGroup}`);
  fileLog.log(`[TriggerActionGroup] uiConfig.showTrigger=${uiConfig.showTrigger}`);

  const [groupName, setGroupName] = useState(
    triggerActionGroup.name || t('TriggerActionGroup.unamed'),
  );

  // 监听 children
  const [children] = useWatchListOperation(triggerActionGroup.children);

  function handleGroupNameChange(name: string) {
    triggerActionGroup.name = name;
    setGroupName(name || t('TriggerActionGroup.unamed'));
  }
  function addTriggerAction() {
    const fnLog = fileLog.sub(false, 'addTriggerAction');
    const newTriggerAction = createDefaultTriggerAction();
    fnLog.log(`[addTriggerAction] newTriggerAction.ulid=${newTriggerAction.ulid}`);

    const parent = toParent(triggerActionGroup);
    // 修改：只维护children（存储完整对象），list由后端维护
    if (!parent.children) {
      parent.children = [];
      fnLog.log(`[addTriggerAction] created children array`);
    }
    parent.children.push(newTriggerAction);
    fnLog.log(`[addTriggerAction] pushed object to children, children.length=${parent.children.length}`);
  }

  // 监听 isSequential 变化
  const [isSequential] = useProxyWatch(triggerActionGroup, 'isSequential', triggerActionGroup.isSequential);

  // 切换执行模式
  function handleSequentialChange(event: React.ChangeEvent<HTMLInputElement>) {
    const newValue = event.target.checked;
    fileLog.log('[TriggerActionGroup] handleSequentialChange, newValue:', newValue);
    triggerActionGroup.isSequential = newValue;
  }
  return (
    <TriggerActionGroupContext.Provider value={triggerActionGroup}>
      <Box
        sx={{ border: '2px solid rgb(217, 217, 217)', padding: '4px' }}
        {...childToProjectDataUtils.triggerActionGroup.getTriggerActionGroupElementByProp(triggerActionGroup.list)}
        data-id-trigger-action-group={triggerActionGroup.id}>
        <Grid2 container sx={{ alignItems: 'center' }}>
          <Grid2 container sx={{ alignItems: 'center' }}>
            {/* 根据 showTrigger 决定是否显示触发器图标 */}
            {uiConfig.showTrigger && <NotificationsNoneIcon />}
            <HandymanIcon />
            <TableRowsIcon />
          </Grid2>
          <Grid2 size={'grow'} sx={{ alignItems: 'center', width: '100%' }}>
            <Box sx={{ width: '100%' }}>
              <EditableText setText={handleGroupNameChange}>
                <span data-id="rename-groupname-btn-a322" style={{ backgroundColor: 'red' }}>
                  {groupName}
                </span>
              </EditableText>
            </Box>
          </Grid2>
          {/* 根据 allowAddGroup 决定是否显示顺序切换和添加按钮 */}
          {uiConfig.allowAddGroup && (
            <>
              <Grid2>
                <Tooltip
                  title={
                    isSequential ? '顺序执行:按顺序逐个执行 TriggerAction' : '并发执行:同时执行所有 TriggerAction'
                  }>
                  <FormControlLabel
                    control={
                      <Switch
                        data-testid="TriggerActionGroup__sequentialSwitch__01JFXYZV2K6L7M8N9O0P1Q2R3"
                        checked={isSequential}
                        onChange={handleSequentialChange}
                        data-id="trigger-action-group-sequential-switch"
                      />
                    }
                    label={'顺序'}
                  />
                </Tooltip>
              </Grid2>
              <Grid2>
                <Box>
                  <IconButton
                    data-testid="TriggerActionGroup__addButton__01JFXYZW3L7M8N9O0P1Q2R3S4"
                    data-id="add-trigger-action-btn.22fab779-75e2-4e34-82f4-64667e7fc017"
                    onClick={addTriggerAction}>
                    <AddIcon />
                  </IconButton>
                </Box>
              </Grid2>
            </>
          )}
        </Grid2>
        <Box>
          {/* 修改：直接循环children而不是list */}
          {children?.map((triggerAction, index) => {
            fileLog.log(`[TriggerActionGroup] render index=${index}, triggerAction.ulid=${triggerAction?.ulid}`);
            if (!triggerAction) {
              fileLog.error(`[TriggerActionGroup] triggerAction is undefined at index=${index}`);
              return null;
            }
            return <TriggerAction key={getUpdateVersion(triggerAction).version} triggerAction={triggerAction} triggerActionGroup={triggerActionGroup} index={index} />;
          })}
        </Box>
      </Box>
    </TriggerActionGroupContext.Provider>
  );
}
