import { Log } from '@fanfanlo'
import { projectStore, IProject } from '@droid/project-v2-interface'
import { createNodeTriggerActionPair } from './nodeClickUtils'
import { ITriggerNodeTriggerData } from '../../../../../iproject/triggers/a11y/node-trigger/ITriggerNodeTrigger'

const fileLog = new Log(false, 'handleNodeClickAction_f')
fileLog.pause = false
fileLog.childrenPaused = false

/**
 * A11y 节点数据结构(从 Android 端传来)
 */
interface A11yNodeData {
    pn: string | null
    an: string | null
    cn: string | null
    node: any | null
}

// 这个方法要进行比较大的改造.
// 参看这个说明 C:\work\ai-conversations\docs\web\08.悬浮窗选择自动点击节点的说明.md
/**
 * 处理添加节点点击配置的 action
 *
 * @param project - 当前 project 数据
 * @param action - URL 参数中的 action 值
 * @param dataBase64 - URL 参数中的 data 值(base64编码)
 * @returns 是否处理成功
 */
export async function handleNodeClickAction(
    project: IProject,
    action: string | null | undefined,
    dataBase64: string | null | undefined
): Promise<boolean> {
    fileLog.log('handleNodeClickAction called')
    fileLog.log('action =', action)
    fileLog.log('dataBase64 =', dataBase64)

    // 检查 action 是否为 addNodeClick
    if (action !== 'addNodeClick') {
        fileLog.log('action is not addNodeClick, skipping')
        return false
    }

    // 检查 dataBase64 是否存在
    if (!dataBase64) {
        fileLog.error('dataBase64 is null or undefined')
        return false
    }

    try {
        // 解码 base64 (使用 UTF-8 安全解码)
        fileLog.log('decoding base64...')
        const dataJson = decodeBase64ToUTF8(dataBase64)
        fileLog.log('dataJson =', dataJson)

        // 解析 JSON
        fileLog.log('parsing JSON...')
        const nodeData: A11yNodeData = JSON.parse(dataJson)
        fileLog.log('nodeData =', nodeData)

        // 验证数据完整性
        fileLog.log('validating data...')
        if (!nodeData.pn) {
            fileLog.error('pn is missing')
            return false
        }

        if (!nodeData.an) {
            fileLog.error('an is missing')
            return false
        }

        if (!nodeData.node) {
            fileLog.error('node is missing')
            return false
        }

        fileLog.log('data validation passed')
        fileLog.log('pn =', nodeData.pn)
        fileLog.log('an =', nodeData.an)
        fileLog.log('cn =', nodeData.cn)
        fileLog.log('node =', nodeData.node)

        // TODO: 重复检测功能需要基于新的 selectorChain 数据结构重新实现
        // 当前暂时跳过重复检测
        fileLog.log('skipping duplicate check (需要基于 selectorChain 重新实现)')

        // 创建新的 triggerAction
        fileLog.log('creating new triggerAction with node trigger')

        // 创建新的 triggerAction 对 (trigger + action)
        const newTriggerAction = createNodeTriggerActionPair(
            nodeData.pn!,
            nodeData.an!,
            nodeData.cn,
            nodeData.node
        )
        fileLog.log('newTriggerAction created:', newTriggerAction.id)

        // 添加到 children[0] (triggerActionGroup)
        if (!project.children || project.children.length === 0) {
            fileLog.error('project.children is empty')
            return false
        }
        const triggerActionGroup = project.children[0]
        fileLog.log('triggerActionGroup.ulid =', triggerActionGroup.ulid)

        if (!triggerActionGroup.children) {
            fileLog.log('initializing triggerActionGroup.children')
            triggerActionGroup.children = []
        }
        triggerActionGroup.children.push(newTriggerAction)
        fileLog.log('added object to triggerActionGroup.children, total count =', triggerActionGroup.children.length)

        // 保存 project
        fileLog.log('saving project...')
        try {
            projectStore.saveProject(project)
            fileLog.log('project saved successfully')
            // alert('节点配置已添加')
        } catch (error) {
            fileLog.error('failed to save project:', error)
            alert('保存失败')
            return false
        }

        fileLog.log('handleNodeClickAction completed')
        return true
    } catch (error) {
        fileLog.error('Error in handleNodeClickAction:', error)
        return false
    }
}

/**
 * 将 UTF-8 编码的 Base64 字符串解码为原始字符串
 * 支持中文和其他非 Latin1 字符
 *
 * @param base64 - Base64 编码的字符串
 * @returns 解码后的字符串
 */
function decodeBase64ToUTF8(base64: string): string {
    fileLog.log('decodeBase64ToUTF8 called with base64 length =', base64.length)

    try {
        // 步骤 1: 使用 atob 将 Base64 解码为二进制字符串
        const binaryString = atob(base64)
        fileLog.log('binaryString length =', binaryString.length)

        // 步骤 2: 将二进制字符串转换为字节数组
        const utf8Bytes = new Uint8Array(binaryString.length)
        for (let i = 0; i < binaryString.length; i++) {
            utf8Bytes[i] = binaryString.charCodeAt(i)
        }
        fileLog.log('utf8Bytes length =', utf8Bytes.length)

        // 步骤 3: 使用 TextDecoder 将 UTF-8 字节数组解码为字符串
        const decoder = new TextDecoder('utf-8')
        const result = decoder.decode(utf8Bytes)
        fileLog.log('result length =', result.length)

        return result
    } catch (error) {
        fileLog.error('decodeBase64ToUTF8 error:', error)
        throw error
    }
}

